'use strict';

// Key 包常量：版本 1 公开信封格式与字节级长度约束。

const FORMAT = 'aigc-key-package';
const VERSION = 1;
const SIGNATURE_KEY_ID = 'owner-key-v1';

const CIPHER_NAME = 'AES-256-GCM';
const SIGNATURE_NAME = 'Ed25519';

// 字节级长度约束（Base64 为 RFC 4648 标准，带填充）
const AES_KEY_BYTES = 32;
const IV_BYTES = 12;
const AUTH_TAG_BYTES = 16;
const ED25519_SIGNATURE_BYTES = 64;
const ED25519_PUBLIC_KEY_BYTES = 32;

// 文件限长（导入第一步）
const MAX_PACKAGE_BYTES = 5 * 1024 * 1024;

// RFC 4648 标准 Base64（带填充）
const BASE64_PATTERN = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;

module.exports = {
  FORMAT,
  VERSION,
  SIGNATURE_KEY_ID,
  CIPHER_NAME,
  SIGNATURE_NAME,
  AES_KEY_BYTES,
  IV_BYTES,
  AUTH_TAG_BYTES,
  ED25519_SIGNATURE_BYTES,
  ED25519_PUBLIC_KEY_BYTES,
  MAX_PACKAGE_BYTES,
  BASE64_PATTERN
};
